@partial(jit, static_argnums=0)        
def Qisaq(self,
          Xisa:jnp.ndarray, # Joint strategy
          Tisas:jnp.ndarray=None, # Optional transition for speed-up
          ) -> jnp.ndarray:  # Average state-action values
    """Compute average state-action values Qisa, given joint strategy `Xisa`"""
    Risar = self.Risar(Xisa)
    b_ivrv_ = self.b_ivrv_
    Visv = self.Visv(Xisa) 
    Tisas = self.Tisas(Xisa) if Tisas is None else Tisas 

    i = 0; s = 1; a = 2; s_ = 3; v = 4; v_ = 5; r = 6
    nextQisaq = jnp.einsum(Tisas, [i,s,a,s_], Visv, [i,s_,v], [i,s,a,v],
                           optimize=self.opti)

    Qisaq = jnp.einsum(b_ivrv_, [i,v,r,v_], Risar, [i,s,a,r], nextQisaq, [i,s,a,v_], [i,s,a,v])
    
    return Qisaq

qbaseSARSA.Qisaq = Qisaq

