@partial(jit, static_argnums=0)
def Qis(self:qbaseSARSA,
        Xisa) -> jnp.ndarray:    
    """
    Compute Q-value for state `s`
    """
    Qisaq = self.Qisaq(Xisa)
    Qisa = jnp.einsum('ijkl,l->ijk', Qisaq, self.gridpoints)
    i = 0; a = 1; s = 2
    Qis = jnp.einsum(Qisa, [i, s, a], Xisa, [i, s, a], [i, s])
    return Qis

qbaseSARSA.Qis = Qis

