# Test: quantile of Q(i,s,a,q) distribution
@partial(jit, static_argnums=0)        
def _Qisa(self,
          Xisa:jnp.ndarray, # Joint strategy
          ) -> jnp.ndarray:  # Average state-action values
    Qisaq = self.Qisaq(Xisa)
    gpoints = jnp.ones((self.nr)) * -1
    gpoints = gpoints.at[:].set(self.gridpoints)
    if self.method=='mean':  # take mean
        _Qisa = jnp.einsum('ijkl,l->ijk', Qisaq, gpoints)
    elif self.method=='quantile':  # use quantile
        _Qisa = quantile(self.tau, Qisaq, gpoints)
    elif self.method=='expectile':
        _Qisa = expectile(self.tau, Qisaq, gpoints)
    elif self.method=='weights':
        Qis = self.Qis(Xisa)
        Qisa = jnp.repeat(Qis[..., jnp.newaxis], self.M, axis=-1)
        w = jnp.ones((self.N, self.Z, self.M, len(self.gridpoints)))
        n = jnp.newaxis
        upper = self.gridpoints[n,n,n,:] >= Qisa[:,:,:,n]
        upper = upper * (self.wU - 1)
        w = w + upper
        wQisaq = weights(w, Qisaq, gpoints)
        _Qisa = jnp.einsum('ijkl,l->ijk', wQisaq, gpoints)  # take the new distrib's mean
    return _Qisa

qbaseSARSA._Qisa = _Qisa  # Monkey-patching - possibly problematic?

# %% qBaseSARSA.ipynb 20
@partial(jit, static_argnums=(0,2))
def TDerror(self:qbaseSARSA,
            Xisa,  # Behavior profiles
            norm=False) -> jnp.ndarray:
    """
    Compute reward-prediction/temporal-difference error for 
    strategy actor-critic dynamics, given joint strategy `Xisa`.
    """
    Q = self._Qisa(Xisa)
    n = jnp.newaxis
    E = Q - (1 / self.beta[:,n,n]) * jnp.log(Xisa)
    E *= self.beta[:,n,n]
    
    E = E - E.mean(axis=2, keepdims=True) if norm else E
    return E

qbaseSARSA.TDerror = TDerror
